@import '../../styles/control-elevation.css';
@import '../../utils/chrome-layout.css';
@import '../../utils/focus-ring.css';
@import '../../utils/forced-colors.css';
@import '../../utils/text-decoration.css';
@import '../../utils/visually-hidden.css';

:host {
  display: block;
  min-width: 0;
  box-sizing: border-box;
}

:host([hidden]) {
  display: none;
}

.bar-action {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  height: var(--dimension-size-600);
  border-radius: var(--dimension-radius-125);
  background: var(--color-background-bold-brand);
  color: var(--color-foreground-on-bold-background-secondary);
  --ds-focus-ring-color: var(--color-interaction-on-bold-background-focus);
}

.bar-action[hidden],
.bar-action__actions--empty {
  display: none;
}

.bar-action__copy,
.bar-action__actions {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: var(--dimension-space-050);
}

.bar-action__copy {
  flex: 1 1 auto;
  padding-inline: var(--dimension-space-100);
}

.bar-action__count {
  flex: 0 1 auto;
  min-width: 0;
}

.bar-action__separator,
.bar-action__clear,
.bar-action__actions {
  flex: 0 0 auto;
}

.bar-action__actions {
  margin-inline-start: auto;
}

.bar-action__actions slot {
  display: contents;
}

.bar-action__clear {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-block-size: var(--dimension-size-400);
  margin: 0;
  padding: var(--dimension-space-025);
  border: 0;
  border-radius: var(--dimension-radius-050);
  background: transparent;
  cursor: pointer;
}

@media (forced-colors: active) {
  .bar-action {
    --ds-control-elevation-shadow: none;
    --ds-control-elevation-highlight: none;
    outline: var(--dimension-stroke-width-012) solid var(--ds-forced-color-control-boundary);
    outline-offset: calc(-1 * var(--dimension-stroke-width-012));
  }
}

import {
  Component,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Prop,
  State,
} from '@stencil/core';

@Component({
  tag: 'ds-bar-action',
  styleUrl: 'BarAction.css',
  scoped: true,
})
export class BarAction {
  @Element() el!: HTMLElement;

  /** Number of selected items. The bar is hidden while this is below one. */
  @Prop() count: number = 0;

  /** Localized noun shown after the count. */
  @Prop() selectedLabel: string = 'selected';

  /** Visible Clear control label. */
  @Prop() clearLabel: string = 'Clear';

  /** Accessible name for the selected-set action group. */
  @Prop() label: string = 'Selected item actions';

  /** Emitted when Clear is activated. The application owns the selected identities. */
  @Event() dsClear!: EventEmitter<MouseEvent>;

  @State() private hasActions = false;

  private actionsObserver?: MutationObserver;

  componentWillLoad() {
    this.updateActionsPresence();
  }

  componentDidLoad() {
    this.updateActionsPresence();
    if (typeof MutationObserver === 'undefined') return;
    this.actionsObserver = new MutationObserver(this.updateActionsPresence);
    this.actionsObserver.observe(this.el, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['slot'],
    });
  }

  disconnectedCallback() {
    this.actionsObserver?.disconnect();
  }

  private get resolvedCount(): number {
    if (!Number.isFinite(this.count)) return 0;
    return Math.max(0, Math.trunc(this.count));
  }

  private get isVisible(): boolean {
    return this.resolvedCount >= 1;
  }

  private updateActionsPresence = () => {
    this.hasActions = Boolean(this.el.querySelector('[slot="actions"]'));
  };

  private handleClear = (event: MouseEvent) => {
    this.dsClear.emit(event);
  };

  render() {
    const countLabel = `${this.resolvedCount} ${this.selectedLabel}`;
    return (
      <Host>
        <div
          class="bar-action ds-chrome-row ds-chrome-space--md ds-control-elevation ds-control-elevation--md"
          hidden={!this.isVisible || undefined}
          role="group"
          aria-label={this.label}
        >
          <div class="bar-action__copy">
            <ds-text
              class="bar-action__count"
              as="span"
              variant="text-body-medium"
              color="inherit"
              fontFeature="tabular-nums"
              lineTruncation={1}
            >
              {countLabel}
            </ds-text>
            <ds-text
              class="bar-action__separator"
              as="span"
              variant="text-body-medium"
              color="inherit"
              aria-hidden="true"
            >
              ·
            </ds-text>
            <button
              class="bar-action__clear ds-text-action ds-text-action--on-bold ds-focus-ring"
              type="button"
              onClick={this.handleClear}
            >
              <ds-text as="span" variant="text-body-medium" color="inherit">
                {this.clearLabel}
              </ds-text>
            </button>
          </div>
          <div
            class={{
              'bar-action__actions': true,
              'bar-action__actions--empty': !this.hasActions,
            }}
          >
            <slot name="actions" />
          </div>
        </div>
        <span
          class="bar-action__status ds-visually-hidden"
          role="status"
          aria-live="polite"
          aria-atomic="true"
        >
          {this.isVisible ? countLabel : ''}
        </span>
      </Host>
    );
  }
}
